import React, { useMemo } from 'react';

import { clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

const cn = (...inputs) => twMerge(clsx(inputs));

export default function CalendarMonthView({
    currentDate,
    slots = [],
    bookings = {},
    onDateClick
}) {
    const today = new Date();
    const todayYmd = today.toLocaleDateString('en-CA');

    // Generate Calendar Grid
    const { days } = useMemo(() => {
        const year = currentDate.getFullYear();
        const month = currentDate.getMonth(); // 0-indexed

        const firstDayOfMonth = new Date(year, month, 1);
        const lastDayOfMonth = new Date(year, month + 1, 0);

        const startDate = new Date(firstDayOfMonth);
        startDate.setDate(startDate.getDate() - startDate.getDay()); // Start on Sunday

        const endDate = new Date(lastDayOfMonth);
        if (endDate.getDay() !== 6) {
            endDate.setDate(endDate.getDate() + (6 - endDate.getDay()));
        }

        const d = new Date(startDate);
        const grid = [];
        while (d <= endDate) {
            grid.push(new Date(d));
            d.setDate(d.getDate() + 1);
        }

        return {
            days: grid,
            monthLabel: firstDayOfMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })
        };
    }, [currentDate]);

    // Aggregate Data per Day
    // slots is array of all active slots. We filter by date string.
    const dailyStats = useMemo(() => {
        const stats = {}; // "YYYY-MM-DD": { revenue: 0, bookingCount: 0, blockCount: 0 }

        slots.forEach(slot => {
            if (!slot.date) return;
            const dateStr = slot.date;

            if (!stats[dateStr]) {
                stats[dateStr] = { revenue: 0, distinctBookings: new Set(), blockCount: 0 };
            }

            // Exclude Open Play Blocks and Blockers from revenue and booking count
            const parentBooking = bookings[slot.bookingId];
            if (parentBooking && parentBooking.type === "OPEN_PLAY_BLOCK") return;

            stats[dateStr].revenue += (slot.price || 0);
            stats[dateStr].distinctBookings.add(slot.bookingId);
        });

        return stats;
    }, [slots]);

    return (
        <div className="flex flex-col h-full bg-white">
            {/* Grid Header */}
            <div className="grid grid-cols-7 border-b border-slate-200 bg-slate-50">
                {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                    <div key={day} className="py-2 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
                        {day}
                    </div>
                ))}
            </div>

            {/* Grid Body */}
            <div className="flex-1 grid grid-cols-7 grid-rows-5 lg:grid-rows-6 divide-x divide-y divide-slate-200 bg-slate-200 border-b border-slate-200">
                {days.map((date, idx) => {
                    const dateYmd = date.toLocaleDateString('en-CA');
                    const isCurrentMonth = date.getMonth() === currentDate.getMonth();
                    const isToday = dateYmd === todayYmd;
                    const stat = dailyStats[dateYmd] || { revenue: 0, distinctBookings: new Set() };
                    const count = stat.distinctBookings.size;

                    return (
                        <div
                            key={dateYmd}
                            onClick={() => onDateClick(date)}
                            className={cn(
                                "relative bg-white p-2 min-h-[80px] hover:bg-slate-50 transition-colors cursor-pointer flex flex-col gap-1",
                                !isCurrentMonth && "bg-slate-50 text-slate-400"
                            )}
                        >
                            {/* Date Number */}
                            <span className={cn(
                                "text-sm font-medium h-7 w-7 flex items-center justify-center rounded-full mb-1",
                                isToday ? "bg-slate-900 text-white" : "text-slate-700"
                            )}>
                                {date.getDate()}
                            </span>

                            {/* Indicators */}
                            {count > 0 && (
                                <div className="flex flex-col gap-1">
                                    <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-emerald-100 text-emerald-800">
                                        {count} {count === 1 ? 'Booking' : 'Bookings'}
                                    </span>
                                    {stat.revenue > 0 && (
                                        <span className="text-[10px] font-medium text-slate-500 pl-1">
                                            ₱{stat.revenue.toLocaleString()}
                                        </span>
                                    )}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
